#!/usr/bin/env node
// Generates each tool's subagent files from the canonical definitions in
// .agents/agents/<name>.md (frontmatter: name, description; body: the prompt).
//
//   node scripts/agents/sync.mjs           write .claude/agents, .kiro/agents, .codex/agents
//   node scripts/agents/sync.mjs --check   exit 1 if any generated file is missing or stale
//
// Read-only reviewers: every generated agent gets read/search/shell tools only
// (Codex: sandbox_mode = "read-only"). No dependencies: runs on plain Node 18+.
import { readFileSync, writeFileSync, readdirSync, mkdirSync, existsSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const SRC = join(ROOT, '.agents', 'agents');
const check = process.argv.includes('--check');

const HEADER = 'Generated by scripts/agents/sync.mjs from .agents/agents/{name}.md. Edit that file, not this one.';

function parse(file) {
  const text = readFileSync(join(SRC, file), 'utf8');
  const m = text.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!m) throw new Error(`${file}: missing frontmatter`);
  const meta = {};
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^(\w+):\s*(.*)$/);
    if (kv) meta[kv[1]] = kv[2].trim();
  }
  if (!meta.name || !meta.description) throw new Error(`${file}: needs name and description`);
  if (`${meta.name}.md` !== file) throw new Error(`${file}: name must match the file name`);
  return { ...meta, body: m[2].trim() + '\n' };
}

const yamlString = (s) => JSON.stringify(s); // a JSON string is a valid YAML scalar
const tomlString = (s) => JSON.stringify(s); // and a valid TOML basic string

const targets = {
  claude: (a) => [
    join('.claude', 'agents', `${a.name}.md`),
    `---\nname: ${a.name}\ndescription: ${yamlString(a.description)}\ntools: Read, Grep, Glob, Bash\n---\n\n` +
      `<!-- ${HEADER.replace('{name}', a.name)} -->\n\n${a.body}`,
  ],
  kiro: (a) => [
    join('.kiro', 'agents', `${a.name}.md`),
    `---\nname: ${a.name}\ndescription: ${yamlString(a.description)}\ntools: ["read", "grep", "glob", "shell"]\n---\n\n` +
      `<!-- ${HEADER.replace('{name}', a.name)} -->\n\n${a.body}`,
  ],
  codex: (a) => {
    if (a.body.includes("'''")) throw new Error(`${a.name}: body must not contain '''`);
    return [
      join('.codex', 'agents', `${a.name}.toml`),
      `# ${HEADER.replace('{name}', a.name)}\n` +
        `name = ${tomlString(a.name)}\ndescription = ${tomlString(a.description)}\nsandbox_mode = "read-only"\n` +
        `developer_instructions = '''\n${a.body}'''\n`,
    ];
  },
};

const agents = readdirSync(SRC).filter((f) => f.endsWith('.md')).sort().map(parse);
const expected = new Map();
for (const a of agents) for (const gen of Object.values(targets)) {
  const [path, content] = gen(a);
  expected.set(path, content);
}

const problems = [];
for (const [path, content] of expected) {
  const abs = join(ROOT, path);
  const current = existsSync(abs) ? readFileSync(abs, 'utf8') : null;
  if (current === content) continue;
  if (check) problems.push(`${current === null ? 'missing' : 'stale'}: ${path}`);
  else { mkdirSync(dirname(abs), { recursive: true }); writeFileSync(abs, content); console.log(`wrote ${path}`); }
}

// Generated files whose source was deleted.
for (const dir of [['.claude', 'agents'], ['.kiro', 'agents'], ['.codex', 'agents']]) {
  const abs = join(ROOT, ...dir);
  if (!existsSync(abs)) continue;
  for (const f of readdirSync(abs)) {
    const path = join(...dir, f);
    if (expected.has(path) || !readFileSync(join(abs, f), 'utf8').includes('Generated by scripts/agents/sync.mjs')) continue;
    if (check) problems.push(`orphan: ${path}`);
    else { rmSync(join(abs, f)); console.log(`removed ${path}`); }
  }
}

if (problems.length) {
  console.error(`Agent files are out of sync with .agents/agents/:\n  ${problems.join('\n  ')}\nRun: node scripts/agents/sync.mjs`);
  process.exit(1);
}
if (check) console.log(`agents in sync (${agents.length} agents × ${Object.keys(targets).length} tools)`);
